import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const locales = ['en', 'bg', 'de', 'el', 'ro', 'sr', 'ru', 'uk', 'tr'];
const sourceCatalog = JSON.parse(await readFile(path.join(root, 'i18n', 'source-catalog.json'), 'utf8'));
const preserve = JSON.parse(await readFile(path.join(root, 'i18n', 'preserve.json'), 'utf8')).entries;
const legacy = JSON.parse(await readFile(path.join(root, 'i18n', 'legacy-messages.json'), 'utf8'));

const exact = Object.fromEntries(locales.map((locale) => [locale, {}]));
const compact = Object.fromEntries(locales.map((locale) => [locale, {}]));

function addRow(source, translations, compactTranslations = {}) {
	const sourceVariants = new Set([
		source,
		source.replaceAll('’', "'").replaceAll('‘', "'"),
		source.replaceAll("'", '’').replaceAll('‘', '’')
	]);
	for (const locale of locales.slice(1)) {
		for (const sourceVariant of sourceVariants) {
			if (translations[locale]) exact[locale][sourceVariant] = translations[locale];
			if (compactTranslations[locale]) compact[locale][sourceVariant] = compactTranslations[locale];
		}
	}
}

