function escapeRegExp(value) {
	return value.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
}

function applyGlossary(source, locale) {
	let result = source;
	const pairs = [...(glossary[locale] ?? [])].sort((left, right) => right[0].length - left[0].length);
	for (const [from, to] of pairs) {
		const boundary = /[\p{L}\p{N}]/u.test(from[0]) && /[\p{L}\p{N}]/u.test(from.at(-1));
		const pattern = boundary
			? new RegExp(`(?<![\\p{L}\\p{N}])${escapeRegExp(from)}(?![\\p{L}\\p{N}])`, 'giu')
			: new RegExp(escapeRegExp(from), 'giu');
		result = result.replace(pattern, to);
	}
	return result;
}

function patternTranslation(source, locale) {
	let match = source.match(/^(.+) \|\| AutoDeal - Car Dealer, Rental & Listing React Nextjs Template$/u);
	if (match) {
		const prefix = applyGlossary(match[1], locale);
		return `${prefix} || ${localizedTitleSuffix[locale]}`;
	}
	match = source.match(/^(.*) car price$/iu);
	if (match) {
		const subject = match[1];
		return {
			bg: `${subject}: цена на автомобил`, de: `${subject}: Fahrzeugpreis`, el: `${subject}: τιμή αυτοκινήτου`, ro: `${subject}: preț mașină`,
			sr: `${subject}: цена аутомобила`, ru: `${subject}: цена автомобиля`, uk: `${subject}: ціна автомобіля`, tr: `${subject}: araç fiyatı`
		}[locale];
	}
	match = source.match(/^([\d,]+) Car$/u);
	if (match) {
		return { bg: `${match[1]} автомобила`, de: `${match[1]} Fahrzeuge`, el: `${match[1]} αυτοκίνητα`, ro: `${match[1]} mașini`, sr: `${match[1]} аутомобила`, ru: `${match[1]} автомобилей`, uk: `${match[1]} автомобілів`, tr: `${match[1]} araç` }[locale];
	}
	match = source.match(/^([\d,]+) Reviews$/u);
	if (match) return { bg: `${match[1]} отзива`, de: `${match[1]} Bewertungen`, el: `${match[1]} κριτικές`, ro: `${match[1]} recenzii`, sr: `${match[1]} рецензија`, ru: `${match[1]} отзывов`, uk: `${match[1]} відгуків`, tr: `${match[1]} değerlendirme` }[locale];
	match = source.match(/^([\d,]+) Rating and Reviews$/u);
	if (match) return { bg: `Рейтинг и отзиви: ${match[1]}`, de: `Bewertung und Rezensionen: ${match[1]}`, el: `Αξιολόγηση και κριτικές: ${match[1]}`, ro: `Evaluări și recenzii: ${match[1]}`, sr: `Оцена и рецензије: ${match[1]}`, ru: `Оценка и отзывы: ${match[1]}`, uk: `Оцінка та відгуки: ${match[1]}`, tr: `Puan ve değerlendirmeler: ${match[1]}` }[locale];
	match = source.match(/^Home Page (\d{2})$/u);
	if (match) return { bg: `Начална страница ${match[1]}`, de: `Startseite ${match[1]}`, el: `Αρχική σελίδα ${match[1]}`, ro: `Pagina principală ${match[1]}`, sr: `Почетна страница ${match[1]}`, ru: `Главная страница ${match[1]}`, uk: `Головна сторінка ${match[1]}`, tr: `Ana Sayfa ${match[1]}` }[locale];
	match = source.match(/^Listing (grid|list|map|detail)(?: V([1-5]))?$/u);
	if (match) return applyGlossary(source, locale);
	match = source.match(/^Show: (\d+)$/u);
	if (match) return { bg: `Покажи: ${match[1]}`, de: `Anzeigen: ${match[1]}`, el: `Εμφάνιση: ${match[1]}`, ro: `Arată: ${match[1]}`, sr: `Прикажи: ${match[1]}`, ru: `Показать: ${match[1]}`, uk: `Показати: ${match[1]}`, tr: `Göster: ${match[1]}` }[locale];
	return null;
}

function translate(source, locale) {
	if (locale === 'en') return source;
	if (exact[locale][source]) return exact[locale][source];
	if (legacy[locale]?.[source]) return legacy[locale][source];
	if (preserve[source]) return source;
	const patterned = patternTranslation(source, locale);
	if (patterned) return patterned;
	const glossed = applyGlossary(source, locale);
	return glossed === source ? null : glossed;
}

